exports.decodeVarints=function(chunks) {
  const result=[];
  for(const chunk of chunks) {
    let value=0,shift=0;
    for(const byte of chunk) {
      value |= (byte & 127) << shift;
      if(byte & 128) shift+=7;
      else {result.push(BigInt(value));value=0;shift=0;}
    }
  }
  return result;
};

