const test=require('node:test');
const assert=require('node:assert/strict');
const {decodeVarints}=require('../varints.cjs');
test('all chunk boundaries and exact unsigned integers',()=>{
  const bytes=Uint8Array.from([0,127,128,1,172,2,255,255,255,255,255,255,255,255,255,1]);
  const expected=[0n,127n,128n,300n,18446744073709551615n];
  for(let split=0;split<=bytes.length;split++) {
    assert.deepEqual(decodeVarints([bytes.slice(0,split),new Uint8Array(),bytes.slice(split)]),expected);
  }
  assert.deepEqual(decodeVarints((function*(){for(const b of bytes)yield Uint8Array.of(b);})()),expected);
  assert.deepEqual(decodeVarints([]),[]);
  assert.equal(bytes[2],128);
});
test('truncation overflow and nonminimal forms',()=>{
  for(const bytes of [[128],[128,0],[129,0],[255,255,255,255,255,255,255,255,255,2],Array(11).fill(128)]) {
    assert.throws(()=>decodeVarints([Uint8Array.from(bytes),new Uint8Array()]),RangeError);
  }
});

