exports.decodeVarints=function(chunks) {
  const result=[];
  let value=0n,count=0;
  for(const chunk of chunks) {
    for(const byte of chunk) {
      count++;
      const payload=byte & 127;
      if(count>10 || (count===10 && (byte & 128 || payload>1))) throw new RangeError('varint overflow');
      value |= BigInt(payload) << BigInt(7*(count-1));
      if(!(byte & 128)) {
        if(count>1 && payload===0) throw new RangeError('nonminimal varint');
        result.push(value);value=0n;count=0;
      }
    }
  }
  if(count) throw new RangeError('unfinished varint');
  return result;
};

